import{r as l,o as a,a as i,b as t,d as s,F as n,c as o,e}from"./app.756eaed4.js";import{_ as d}from"./plugin-vue_export-helper.21dcd24c.js";const c={},g=o('<h1 id="troubleshooting-using-log-files" tabindex="-1"><a class="header-anchor" href="#troubleshooting-using-log-files" aria-hidden="true">#</a> Troubleshooting using log files</h1><p>You can configure logging for IBM IMS Explorer for VS Code to produce detailed logs that help troubleshoot problems by providing more information and traces of the extension&#39;s activities. Enable logging through the VS Code setting <code>ims.explorer.logging.level</code>. In the VS Code Preferences editor, you can select from the available <a href="#log-levels">log levels</a>: <code>DEBUG</code>, <code>INFO</code> (default), <code>WARN</code>, <code>ERROR</code>, and <code>OFF</code>.</p><p>After logging is enabled, log output can be found in the VS Code <strong>Output</strong> panel. Open it with <strong>View &gt; Output</strong> and select the relevant channel from the drop-down list:</p><ul><li><strong>IBM IMS Explorer for VS Code</strong> \u2014 Client-side logs for connections, catalog browsing, and general extension activity.</li><li><strong>IBM IMS Explorer LSP Server</strong> \u2014 Language server logs. Any JDBC or SQL-related errors appear in this channel.</li></ul>',4),h=e("A log file written to your disk can be shared with technical support or attached to an issue filed against the "),p={href:"https://github.com/IBM/ims-explorer-about/issues",target:"_blank",rel:"noopener noreferrer"},u=e("public issues repository on GitHub"),f=e("."),m=o('<p>Additional details for each log are provided in the table below.</p><h2 id="locate-log-files-manually" tabindex="-1"><a class="header-anchor" href="#locate-log-files-manually" aria-hidden="true">#</a> Locate log files manually</h2><p>Log files are written to the VS Code extension logs directory. The table below lists the Output view name and typical file locations for each log type.</p><table><thead><tr><th>Log type</th><th>VS Code Output View Name</th><th>Location</th></tr></thead><tbody><tr><td>Main IMS Explorer client log</td><td>IBM IMS Explorer for VS Code</td><td>Log files are located in: <ul><li>Windows example: <code>C:\\Users\\username\\AppData\\Roaming\\Code\\logs\\&lt;timestamp&gt;\\window1\\exthost\\IBM.ims-explorer-for-vscode\\</code></li><li>Mac example: <code>/Users/username/Library/Application Support/Code/logs/&lt;timestamp&gt;/window1/exthost/IBM.ims-explorer-for-vscode/</code></li></ul></td></tr><tr><td>IMS Explorer language server log</td><td>IBM IMS Explorer LSP Server</td><td>Log files are located in the same directory as the client log above. Any JDBC or SQL-related errors are reported here.</td></tr><tr><td>VS Code Extension Host log</td><td>Extension Host</td><td>Log files are located in: <ul><li>Windows example: <code>C:\\Users\\username\\AppData\\Roaming\\Code\\logs\\&lt;timestamp&gt;\\window1\\exthost\\exthost.log</code></li><li>Mac example: <code>/Users/username/Library/Application Support/Code/logs/&lt;timestamp&gt;/window1/exthost/exthost.log</code></li></ul></td></tr></tbody></table><h2 id="log-levels" tabindex="-1"><a class="header-anchor" href="#log-levels" aria-hidden="true">#</a> Log levels</h2><p>IBM IMS Explorer for VS Code uses the log levels described in the following table. These levels are listed in order of most to least detailed (with the exception of <code>OFF</code>, which turns off all logging). For example, the <code>DEBUG</code> setting outputs detailed debug information as well as messages from the other levels below it: <code>INFO</code>, <code>WARN</code>, and <code>ERROR</code>. In contrast, the <code>ERROR</code> setting only logs important errors.</p><table><thead><tr><th>Log level</th><th>Description</th></tr></thead><tbody><tr><td>Debug</td><td>Identifies detailed informational events that are useful for troubleshooting the extension&#39;s behavior.</td></tr><tr><td>Info</td><td>Provides informative messages that are of general interest for observing activities performed by the extension.</td></tr><tr><td>Warn</td><td>Indicates potentially problematic situations that could cause unexpected behaviors or errors.</td></tr><tr><td>Error</td><td>Designates error events that interrupted the extension in executing an operation as intended.</td></tr><tr><td>Off</td><td>Nothing is logged.</td></tr></tbody></table>',7);function b(x,v){const r=l("ExternalLinkIcon");return a(),i(n,null,[g,t("p",null,[h,t("a",p,[u,s(r)]),f]),m],64)}var w=d(c,[["render",b]]);export{w as default};
